import { z } from 'zod';

// Schema for entity deduplication results - updated for OpenAI structured outputs with strict mode
export const EntityDeduplicationSchema = z.object({
  deduplication_groups: z.array(
    z.object({
      canonical_name: z.string().describe('The canonical name to use for this group of duplicate entities'),
      entity_type: z.string().describe('The entity type for this group'),
      duplicate_names: z.array(z.string()).describe('All entity names that refer to the same canonical entity'),
      confidence: z.number().min(0).max(1).describe('Confidence level that these are indeed duplicates (0.0-1.0)'),
      reasoning: z.string().describe('Brief explanation for why these entities are considered duplicates')
    }).strict()
  ).describe('Groups of duplicate entities with their canonical names')
}).strict();

export type EntityDeduplicationResult = z.infer<typeof EntityDeduplicationSchema>;

export interface EntityForDeduplication {
  name: string;
  entity_type: string;
  summary?: string;
  attributes?: Record<string, any>;
}

/**
 * Generate a prompt for identifying duplicate entities in a batch
 */
export function createEntityDeduplicationPrompt(
  entities: EntityForDeduplication[],
  contextInfo?: string
): string {
  const entityList = entities
    .map((entity, index) => {
      const summary = entity.summary ? ` - Summary: ${entity.summary}` : '';
      const attrs = entity.attributes ? 
        ` - Attributes: ${JSON.stringify(entity.attributes)}` : '';
      return `${index + 1}. Name: "${entity.name}" (Type: ${entity.entity_type})${summary}${attrs}`;
    })
    .join('\n');

  const contextSection = contextInfo ? `
<CONTEXT>
${contextInfo}
</CONTEXT>
` : '';

  return `Identify duplicate entities in this list:

<ENTITIES>
${entityList}
</ENTITIES>
${contextSection}
Your task is to identify groups of entities that refer to the same real-world entity. Consider:

**Exact Matches:**
- Identical names
- Case variations (e.g., "john" vs "John")

**Common Variations:**
- Nicknames and full names (e.g., "Bob" and "Robert", "Mike" and "Michael")
- Abbreviations (e.g., "NYC" and "New York City", "USA" and "United States")
- Titles and honorifics (e.g., "Dr. Smith" and "Smith", "Mr. Johnson" and "Johnson")

**Contextual Clues:**
- Same person referred to differently in different contexts
- Organizations with different naming conventions
- Places with alternate names or spellings

**Important Guidelines:**
1. Only group entities if you are confident they refer to the same real-world entity
2. Different people with the same name should NOT be grouped together
3. Use context clues to disambiguate when available
4. For each group, choose the most complete/formal name as canonical
5. Include confidence scores (0.7+ for high confidence, 0.5-0.7 for medium, below 0.5 for low)
6. Provide clear reasoning for each grouping decision

**Conservative Approach:**
When in doubt, do NOT group entities. It's better to have some duplicates than to incorrectly merge distinct entities.

Return only groups where entities are duplicates. Do not include single entities that have no duplicates.`;
}

/**
 * Generate a prompt for validating deduplication results
 */
export function createDeduplicationValidationPrompt(
  originalEntities: EntityForDeduplication[],
  deduplicationResult: EntityDeduplicationResult
): string {
  const groupsText = deduplicationResult.deduplication_groups
    .map((group, index) => {
      return `Group ${index + 1}: "${group.canonical_name}" (${group.entity_type})
  - Duplicates: ${group.duplicate_names.join(', ')}
  - Confidence: ${group.confidence}
  - Reasoning: ${group.reasoning}`;
    })
    .join('\n\n');

  return `Review this deduplication result for accuracy:

<ORIGINAL_ENTITIES>
${originalEntities.map(e => `"${e.name}" (${e.entity_type})`).join(', ')}
</ORIGINAL_ENTITIES>

<PROPOSED_GROUPINGS>
${groupsText}
</PROPOSED_GROUPINGS>

Validate each grouping and check for:
1. Are the entities in each group actually the same real-world entity?
2. Are there any obvious duplicates that were missed?
3. Are there any incorrect groupings that should be separated?
4. Is the canonical name appropriate for each group?

Return a corrected version with any necessary adjustments, or confirm the original result if it's accurate.`;
}